/** Accessibility overlay: never changes the underlying app to open the menu. */
final class FloatingMenu {
 final AgentService service;final WindowManager wm;final Handler handler=new Handler();AgentBubble bubble;ProgressTicker ticker;boolean concealed;String lastTicker="";long tickerUntil;GoalControls goalControls;LinearLayout panel;ScrollView surface;EditText input;WindowManager.LayoutParams bubbleParams;boolean destroyed;
 final Runnable refresh=new Runnable(){public void run(){if(destroyed)return;bubble.state(service.running,service.paused);if(goalControls!=null)goalControls.refresh();if(!lastTicker.equals(AgentService.liveText)){lastTicker=AgentService.liveText;tickerUntil=android.os.SystemClock.uptimeMillis()+8000;ticker.text(lastTicker);}ticker.setVisibility(!concealed&&!AgentService.appVisible&&(service.running||service.paused||android.os.SystemClock.uptimeMillis()<tickerUntil)?View.VISIBLE:View.INVISIBLE);handler.postDelayed(this,600);}};
 FloatingMenu(AgentService s){service=s;wm=(WindowManager)s.getSystemService(Context.WINDOW_SERVICE);bubble=new AgentBubble(s);bubbleParams=new WindowManager.LayoutParams(dp(48),dp(48),WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);bubbleParams.gravity=Gravity.TOP|Gravity.LEFT;bubbleParams.x=s.getSharedPreferences("floating",0).getInt("x",dp(320));bubbleParams.y=s.getSharedPreferences("floating",0).getInt("y",dp(100));bubble.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int ox,oy;boolean drag;public boolean onTouch(View v,android.view.MotionEvent e){switch(e.getAction()){case MotionEvent.ACTION_DOWN:sx=e.getRawX();sy=e.getRawY();ox=bubbleParams.x;oy=bubbleParams.y;drag=false;return true;case MotionEvent.ACTION_MOVE:float dx=e.getRawX()-sx,dy=e.getRawY()-sy;if(Math.hypot(dx,dy)>dp(8))drag=true;if(drag){android.graphics.Rect bounds=wm.getCurrentWindowMetrics().getBounds();bubbleParams.x=Math.max(0,Math.min(bounds.width()-bubble.getWidth(),ox+(int)dx));bubbleParams.y=Math.max(0,Math.min(bounds.height()-bubble.getHeight(),oy+(int)dy));wm.updateViewLayout(bubble,bubbleParams);}return true;case MotionEvent.ACTION_UP:if(!drag){v.performClick();open();}else service.getSharedPreferences("floating",0).edit().putInt("x",bubbleParams.x).putInt("y",bubbleParams.y).apply();return true;}return false;}});wm.addView(bubble,bubbleParams);ticker=new ProgressTicker(s);WindowManager.LayoutParams tp=new WindowManager.LayoutParams(wm.getCurrentWindowMetrics().getBounds().width()-dp(24),dp(38),WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,PixelFormat.TRANSLUCENT);tp.gravity=Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL;tp.y=dp(12)+wm.getCurrentWindowMetrics().getWindowInsets().getInsets(WindowInsets.Type.navigationBars()).bottom;wm.addView(ticker,tp);handler.post(refresh);}
 int dp(int n){return (int)(n*service.getResources().getDisplayMetrics().density);}
 void open(){if(panel!=null){close();return;}panel=Ui.column(service);panel.setPadding(dp(20),dp(20),dp(20),dp(20));
  LinearLayout head=new LinearLayout(service);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(Ui.mark(service,40));LinearLayout wordmark=Ui.column(service);wordmark.setPadding(dp(12),0,0,0);wordmark.addView(Ui.text(service,I18n.text(service,"app_name"),18,Ui.TEXT,true));head.addView(wordmark,new LinearLayout.LayoutParams(0,-2,1));Button dismiss=Ui.button(service,"×",false,this::close);dismiss.setTextSize(22);head.addView(dismiss,new LinearLayout.LayoutParams(dp(48),dp(48)));panel.addView(head);Ui.gap(panel,20);
  goalControls=new GoalControls(service,true,this::close);input=goalControls.goal;panel.addView(goalControls);Ui.gap(panel,14);add(I18n.text(service,"control_center"),()->{close();service.startActivity(new Intent(service,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));});
  surface=new ScrollView(service);surface.setBackground(Ui.shape(service,0xfaffffff,28,true));surface.setClipToOutline(true);surface.setVerticalScrollBarEnabled(false);surface.addView(panel);surface.setElevation(dp(12));int maxHeight=wm.getCurrentWindowMetrics().getBounds().height()-dp(120);panel.measure(View.MeasureSpec.makeMeasureSpec(Math.min(dp(340),wm.getCurrentWindowMetrics().getBounds().width()-dp(24)),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));
  WindowManager.LayoutParams p=new WindowManager.LayoutParams(Math.min(dp(340),wm.getCurrentWindowMetrics().getBounds().width()-dp(24)),Math.min(panel.getMeasuredHeight(),maxHeight),WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL,PixelFormat.TRANSLUCENT);p.gravity=Gravity.CENTER;p.softInputMode=WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE;wm.addView(surface,p);
 }
 void add(String text,Runnable action){panel.addView(Ui.button(service,text,false,action),new LinearLayout.LayoutParams(-1,dp(48)));}
 void conceal(){concealed=true;ticker.setVisibility(View.INVISIBLE);if(surface!=null){surface.setVisibility(View.INVISIBLE);WindowManager.LayoutParams p=(WindowManager.LayoutParams)surface.getLayoutParams();p.flags|=WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE;wm.updateViewLayout(surface,p);((android.view.inputmethod.InputMethodManager)service.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(surface.getWindowToken(),0);}}
 void reveal(){if(destroyed)return;concealed=false;bubble.setVisibility(View.VISIBLE);if(surface!=null){WindowManager.LayoutParams p=(WindowManager.LayoutParams)surface.getLayoutParams();p.flags&=~(WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE);wm.updateViewLayout(surface,p);surface.setVisibility(View.VISIBLE);}}
 void saveDraft(){if(input!=null)GoalSettings.goal(service,input.getText().toString());}
 void hidePanel(){if(surface!=null){wm.removeView(surface);surface=null;}panel=null;goalControls=null;input=null;}
 void close(){saveDraft();hidePanel();}
 void voiceResult(String text,String error){if(destroyed)return;if(text!=null){GoalSettings.goal(service,text);}else service.log(error);open();}
 void destroy(){destroyed=true;handler.removeCallbacks(refresh);close();wm.removeView(bubble);wm.removeView(ticker);}
}
